import type { Vehicle, VehicleClass } from '../types'

function v(
  id: string,
  manufacturer: string,
  name: string,
  cls: VehicleClass,
  price: number,
  seats: number,
  topSpeed: number,
  realLife: string,
  source: string,
  description: string,
  wiki: string,
): Vehicle {
  return {
    id,
    manufacturer,
    name,
    class: cls,
    price,
    seats,
    topSpeed,
    realLife,
    source,
    description,
    wiki: `https://gta.fandom.com/wiki/${wiki}`,
  }
}

